def compute(vars):
    sales_revenue = vars["Sales Revenue"]
    total_assets = vars["Total Assets"]

    if total_assets == 0:
        return {
            "value": None,
            "trace": {
                "Sales Revenue": sales_revenue,
                "Total Assets": total_assets,
                "output_meta": {"currency": None, "scale": None, "unit": "ratio"},
            },
        }

    total_asset_turnover = sales_revenue / total_assets
    return {
        "value": total_asset_turnover,
        "trace": {
            "Sales Revenue": sales_revenue,
            "Total Assets": total_assets,
            "output_meta": {"currency": None, "scale": None, "unit": "ratio"},
        },
    }
